#!/usr/bin/env python3
"""Helper script for third_party/envoy-gateway/update.sh to process Envoy Gateway manifests."""

import sys

import yaml


def process_manifests(
    install_file, gateway_api_file, eg_crds_dst, eg_manifest_dst
):
  """Processes Envoy Gateway and Gateway API manifests for Cloud Robotics Core.

  Args:
    install_file: Path to the upstream install.yaml file.
    gateway_api_file: Path to the downloaded standard-install.yaml file.
    eg_crds_dst: Output path for Envoy Gateway CRDs.
    eg_manifest_dst: Output path for Envoy Gateway controller manifests.
  """
  # 1. Process Gateway API CRDs (verbatim standard channel)
  with open(gateway_api_file, "r", encoding="utf-8") as f:
    gapi_raw = f.read()

  gapi_docs = gapi_raw.split("\n---\n")
  processed_gapi = []
  for doc_str in gapi_docs:
    cleaned = doc_str.strip()
    if not cleaned or cleaned.startswith("# Generated"):
      continue
    processed_gapi.append(cleaned)

  gapi_header = """# Generated by update.sh. DO NOT EDIT!
# ---------------------------------------------------------
# Gateway API Custom Resource Definitions (CRDs) - Standard Channel
# ---------------------------------------------------------
"""
  with open(gateway_api_file, "w", encoding="utf-8") as f:
    f.write(gapi_header + "\n---\n".join(processed_gapi) + "\n")

  # 2. Process Envoy Gateway Manifests
  with open(install_file, "r", encoding="utf-8") as f:
    raw_content = f.read()

  docs_text = raw_content.split("\n---\n")
  eg_crds = []
  system_docs = []

  for doc_str in docs_text:
    cleaned = doc_str.strip()
    if not cleaned:
      continue
    try:
      doc_obj = yaml.safe_load(cleaned)
    except yaml.YAMLError:
      system_docs.append(cleaned)
      continue

    if not doc_obj or not isinstance(doc_obj, dict):
      continue

    kind = doc_obj.get("kind")
    if kind == "CustomResourceDefinition":
      spec = doc_obj.get("spec") or {}
      group = spec.get("group", "")
      # Only include Envoy Gateway proprietary CRDs (*.gateway.envoyproxy.io).
      if group.endswith("gateway.envoyproxy.io"):
        eg_crds.append(cleaned)
    else:
      system_docs.append(cleaned)

  # Write Envoy Gateway CRDs
  eg_crd_header = """# Generated by update.sh. DO NOT EDIT!
# ---------------------------------------------------------
# Envoy Gateway Custom Resource Definitions (CRDs)
# ---------------------------------------------------------
"""
  with open(eg_crds_dst, "w", encoding="utf-8") as f:
    f.write(eg_crd_header + "\n---\n".join(eg_crds) + "\n")

  # Write Envoy Gateway Controller Manifests (wrapped with Helm condition)
  header = """{{- if eq .Values.use_gateway "true" }}
# Generated by update.sh. DO NOT EDIT!
# ---------------------------------------------------------
# Envoy Gateway System Manifests
# ---------------------------------------------------------
"""
  footer = "\n{{- end }}\n"
  with open(eg_manifest_dst, "w", encoding="utf-8") as f:
    f.write(header + "\n---\n".join(system_docs) + footer)

  print(
      f"Successfully processed:\n  - {gateway_api_file}\n  - {eg_crds_dst}\n  -"
      f" {eg_manifest_dst}"
  )


if __name__ == "__main__":
  if len(sys.argv) < 5:
    print(
        f"Usage: {sys.argv[0]} <install_file> <gateway_api_file> <eg_crds_dst>"
        " <eg_manifest_dst>",
        file=sys.stderr,
    )
    sys.exit(1)
  process_manifests(sys.argv[1], sys.argv[2], sys.argv[3], sys.argv[4])
